using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Unity.Profiling;
using Unity.Profiling.LowLevel.Unsafe;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Racing;
using HarborValeGreybox.Launch;
namespace HarborValeGreybox.Presentation {
public class PresentationProbe:MonoBehaviour {
 static string folder;List<string> checks=new List<string>();bool failed;double deadline;
 [Serializable]class ViewStats {public string view;public double meanFrameMs,p95FrameMs,drawCalls,batches,setPasses;public int frames;}
 [Serializable]class Report {public string mode,gpu,api,colorSpace,colliderDigest;public int msaa,staticRenderers,batchedRenderers,detailRenderers,staticColliders;public List<ViewStats> views=new List<ViewStats>();}
 Report report=new Report();ProfilerRecorder draws,batches,passes;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--render-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=Path.Combine(folder,"isolated-v5.json");Application.targetFrameRate=60;}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var g=new GameObject("Rendering native benchmark");DontDestroyOnLoad(g);g.AddComponent<PresentationProbe>();}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;draws.Dispose();batches.Dispose();passes.Dispose();}
 void Log(string t,string s,LogType k){if(!failed&&(k==LogType.Error||k==LogType.Exception)){failed=true;checks.Add("FAIL runtime "+t);Write();Application.Quit(1);}}
 void Check(bool good,string text){checks.Add((good?"PASS ":"FAIL ")+text);if(!good){failed=true;Write();Application.Quit(1);throw new Exception(text);}}
 void Write(){File.WriteAllLines(Path.Combine(folder,"results.txt"),checks);File.WriteAllText(Path.Combine(folder,"metrics.json"),JsonUtility.ToJson(report,true));}
 void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Rendering benchmark timeout");}
 static ProfilerRecorder Counter(string name){var handles=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(handles);foreach(var h in handles){var d=ProfilerRecorderHandle.GetDescription(h);if(d.Name==name)return ProfilerRecorder.StartNew(d.Category,d.Name,1);}return default;}
 IEnumerator View(string name,Vector3 position,Quaternion rotation,float fov){var cam=Camera.main;cam.transform.SetPositionAndRotation(position,rotation);cam.fieldOfView=fov;for(int i=0;i<100;i++)yield return null;var ms=new List<double>();double d=0,b=0,p=0;long previous=System.Diagnostics.Stopwatch.GetTimestamp();for(int i=0;i<180;i++){yield return new WaitForEndOfFrame();long now=System.Diagnostics.Stopwatch.GetTimestamp();ms.Add((now-previous)*1000.0/System.Diagnostics.Stopwatch.Frequency);previous=now;if(draws.Valid)d+=draws.LastValue;if(batches.Valid)b+=batches.LastValue;if(passes.Valid)p+=passes.LastValue;}ms.Sort();report.views.Add(new ViewStats{view=name,frames=ms.Count,meanFrameMs=ms.Average(),p95FrameMs=ms[(int)(ms.Count*.95)],drawCalls=draws.Valid&&d>0?d/ms.Count:-1,batches=batches.Valid&&b>0?b/ms.Count:-1,setPasses=passes.Valid&&p>0?p/ms.Count:-1});ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+180;while(HarborValeLaunch.Instance==null)yield return null;HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);while(FindAnyObjectByType<HarborValeGreybox.Workshop.ExpandedWorkshop>()?.Ready!=true)yield return null;yield return new WaitForSecondsRealtime(2);var car=FindAnyObjectByType<FinchVehicle>();car.externalInput=true;car.commandedPedal=0;car.commandedHandbrake=false;var chase=Camera.main.GetComponent<FinchChaseCamera>();chase.enabled=false;
  bool improved=!CityPresentation.DisabledForComparison;var presentation=FindAnyObjectByType<CityPresentation>();if(improved){while(presentation==null||!presentation.Ready){presentation=FindAnyObjectByType<CityPresentation>();yield return null;}Check(QualitySettings.activeColorSpace==ColorSpace.Linear&&QualitySettings.antiAliasing==4,"Linear color and four-sample edge smoothing enabled");Check(Camera.main.GetComponent<SoftTonemap>()?.Ready==true,"Native tonemap shader supported and active");Check(presentation.BatchedRenderers>1000,"Static city geometry actually batched in player");Check(presentation.DetailRenderers>100,"Static detail distance budget applied");report.staticRenderers=presentation.EligibleStaticRenderers;report.batchedRenderers=presentation.BatchedRenderers;report.detailRenderers=presentation.DetailRenderers;}
  var root=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().First(g=>g.name.StartsWith("HARBOR VALE | scaled"));var colliders=root.GetComponentsInChildren<Collider>().Where(c=>c.GetComponentInParent<StarterCarSpecification>()==null&&c.GetComponentInParent<FinchVehicle>()==null).ToArray();report.staticColliders=colliders.Length;var strings=colliders.Select(c=>c.GetType().Name+"|"+c.name+"|"+c.transform.position.ToString("F4")+"|"+c.transform.rotation.ToString("F4")+"|"+c.transform.lossyScale.ToString("F4")).OrderBy(x=>x).ToArray();File.WriteAllLines(Path.Combine(folder,"static-colliders.txt"),strings);using(var hash=System.Security.Cryptography.SHA256.Create())report.colliderDigest=BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(string.Join("\n",strings)))).Replace("-","");report.mode=improved?"enhanced":"baseline";report.gpu=SystemInfo.graphicsDeviceName;report.api=SystemInfo.graphicsDeviceType.ToString();report.colorSpace=QualitySettings.activeColorSpace.ToString();report.msaa=QualitySettings.antiAliasing;draws=Counter("Draw Calls Count");batches=Counter("Batches Count");passes=Counter("SetPass Calls Count");Check(car.GetComponentsInChildren<WheelCollider>().Length==4,"Rendering retains four physical wheel contacts");Check(car.GetComponentsInChildren<MeshRenderer>().All(r=>!r.isPartOfStaticBatch),"Dynamic car is excluded from static city batches");if(Environment.GetCommandLineArgs().Contains("--shadow-off"))foreach(var light in FindObjectsByType<Light>(FindObjectsSortMode.None))light.shadows=LightShadows.None;
  Vector3 focus=car.transform.position+Vector3.up*1.2f;Vector3 pos=focus-car.transform.forward*7+Vector3.up*2.3f;yield return View("Street",pos,Quaternion.LookRotation(focus+car.transform.forward*2-pos),65);pos=car.transform.position+new Vector3(45,28,-65);yield return View("District",pos,Quaternion.LookRotation(car.transform.position+new Vector3(0,2,45)-pos),65);
  if(improved){var map=Camera.main.GetComponent<MapExplorer>();car.GetComponent<FinchDrivingHUD>().SetInspection(true);yield return new WaitForSecondsRealtime(.6f);Check(Camera.main.farClipPlane>=8000&&!RenderSettings.fog,"Map overview restores long range and disables driving fog");yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,"MapOverview.png"));car.GetComponent<FinchDrivingHUD>().SetInspection(false);yield return new WaitForSecondsRealtime(.2f);Check(Camera.main.farClipPlane==3000&&RenderSettings.fog,"Driving render budget restores after map overview");}
  Check(!failed,"No native runtime rendering errors");Write();Application.Quit(0);
 }
}
}
